  .c-page-banner h2 {
    font-size: 38px;
  }
}
@use 'abstracts' as *;

.c-blog-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.c-blog-card {
  display: flex;
  flex-direction: column;
  min-height: 545px;
  min-width: 0;
}

.c-blog-card__media {
  border-radius: 30px;
  display: block;
  height: 315px;
  overflow: hidden;
}

.c-blog-card__media img {
